package cn.corenyan.matrix;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.io.*;import java.net.URL;import java.net.HttpURLConnection;
public final class MatrixActivity extends Activity {
 private WebView web;private FrameLayout root;private ValueCallback<Uri[]> fileCallback;private static final int PICK_FILE=41,NOTIFY_PERMISSION=42;private String nonce="",downloadUrl,downloadMime,downloadName;private View fullscreen;private WebChromeClient.CustomViewCallback fullscreenCallback;private final ExecutorService io=Executors.newSingleThreadExecutor();
 private String notificationRequestId=null;
 private boolean closing=false;
 private static final int CLOSE_TIMEOUT_MS=650,CLOSE_MAX_MS=500;
 private String notificationPermission(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return getPreferences(MODE_PRIVATE).getBoolean("notificationAsked",false)?"denied":"default";NotificationChannel ch=nm.getNotificationChannel("matrix-replies");return nm.areNotificationsEnabled()&&(ch==null||ch.getImportance()!=NotificationManager.IMPORTANCE_NONE)?"granted":"denied";}
 private boolean trusted(String url){try{Uri a=Uri.parse(MatrixConfig.SERVER_URL),b=Uri.parse(url);return "https".equals(b.getScheme())&&Objects.equals(a.getHost(),b.getHost())&&a.getPort()==b.getPort();}catch(Exception e){return false;}}
 @Override public void onCreate(Bundle state){super.onCreate(state);root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(9,9,9));setContentView(root);root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));web.setBackgroundColor(Color.rgb(9,9,9));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);s.setUserAgentString(s.getUserAgentString()+" "+MatrixConfig.USER_AGENT);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Bridge(),"MatrixBridge");
 web.setWebViewClient(new WebViewClient(){
  @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(trusted(url))return false;if(request.isForMainFrame())openExternal(url);return true;}
  @Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){nonce=UUID.randomUUID().toString();}
  @Override public void onPageFinished(WebView view,String url){CookieManager.getInstance().flush();if(trusted(url))inject();}
  @Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())showOffline();}
  @Override public void onReceivedSslError(WebView view,android.webkit.SslErrorHandler handler,android.net.http.SslError error){handler.cancel();showOffline();}
 });
 web.setWebChromeClient(new WebChromeClient(){
  @Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(!trusted(view.getUrl()))return false;if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");String[] types=params.getAcceptTypes();if(types!=null&&types.length>0&&!types[0].isEmpty())i.putExtra(Intent.EXTRA_MIME_TYPES,types);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(i,PICK_FILE);}catch(ActivityNotFoundException e){fileCallback.onReceiveValue(null);fileCallback=null;toast("没有可用的文件选择器");}return true;}
  @Override public void onShowCustomView(View view,CustomViewCallback callback){if(fullscreen!=null){callback.onCustomViewHidden();return;}fullscreen=view;fullscreenCallback=callback;web.setVisibility(View.GONE);root.addView(view,new FrameLayout.LayoutParams(-1,-1));}
  @Override public void onHideCustomView(){hideFullscreen();}
 });
 web.setDownloadListener((url,ua,disposition,mime,size)->{if(trusted(url))askDownload(url,URLUtil.guessFileName(url,disposition,mime),mime);else toast("请在受信任的 Matrix 页面下载文件");});
 String initialRoute=getIntent().getStringExtra("route");if(initialRoute!=null&&initialRoute.matches("/CHAT(/[a-f0-9-]+)?"))web.loadUrl(MatrixConfig.SERVER_URL+initialRoute);else if(state==null||web.restoreState(state)==null)web.loadUrl(MatrixConfig.SERVER_URL);createChannel();
 }
 private void openExternal(String url){Uri uri=Uri.parse(url);if(!Arrays.asList("https","http").contains(uri.getScheme()))return;try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(ActivityNotFoundException e){toast("无法打开这个链接");}}
 private void inject(){String script="(()=>{const token="+JSONObject.quote(nonce)+";let serial=0;const pending=new Map();addEventListener('matrix-native-result',e=>{const r=pending.get(e.detail.id);if(r){pending.delete(e.detail.id);e.detail.error?r.reject(Error(e.detail.error)):r.resolve(e.detail.value);}});const call=(action,value)=>new Promise((resolve,reject)=>{const id=String(++serial);pending.set(id,{resolve,reject});MatrixBridge.postMessage(token,JSON.stringify({id,action,value}));setTimeout(()=>{if(pending.has(id)){pending.delete(id);reject(Error('Native request timed out'));}},30000);});Object.defineProperty(window,'MatrixNative',{configurable:true,value:Object.freeze({platform:'android',notificationPermission:"+JSONObject.quote(notificationPermission())+",getNotificationPermission:()=>call('getNotificationPermission'),openNotificationSettings:()=>call('openNotificationSettings'),writeImage:base64=>call('writeImage',base64),writeClipboard:text=>call('writeClipboard',text),readClipboard:()=>call('readClipboard'),notify:value=>call('notify',value),requestNotifications:()=>call('requestNotifications'),download:value=>call('download',value)})});dispatchEvent(new Event('matrix-native-ready'));})();";web.evaluateJavascript(script,null);}
 private final class Bridge {@JavascriptInterface public void postMessage(String token,String raw){if(!nonce.equals(token)||raw==null||raw.length()>12000000)return;runOnUiThread(()->{if(!trusted(web.getUrl())||!nonce.equals(token))return;String id="";try{JSONObject p=new JSONObject(raw);id=p.getString("id");Object value=null;switch(p.getString("action")){
 case "writeClipboard":((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Matrix",p.optString("value")));value=true;break;
 case "writeImage":String image=p.getString("value");final String requestId=id;io.submit(()->{try{byte[] bytes=android.util.Base64.decode(image,android.util.Base64.DEFAULT);if(bytes.length>8*1024*1024)throw new IOException();android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=0||options.outHeight<=0||(long)options.outWidth*options.outHeight>32000000)throw new IOException();File dir=new File(getCacheDir(),"clipboard");dir.mkdirs();File out=new File(dir,UUID.randomUUID().toString()+".img");try(FileOutputStream stream=new FileOutputStream(out)){stream.write(bytes);}Uri uri=Uri.parse("content://"+getPackageName()+".downloads/"+out.getName());runOnUiThread(()->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newUri(getContentResolver(),"Matrix image",uri));reply(requestId,true,null);});}catch(Exception e){runOnUiThread(()->reply(requestId,null,"图片无法复制"));}});return;
 case "readClipboard":ClipboardManager clipboard=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);value=clipboard.hasPrimaryClip()?String.valueOf(clipboard.getPrimaryClip().getItemAt(0).coerceToText(MatrixActivity.this)):"";break;
 case "notify":JSONObject n=p.getJSONObject("value");value=notifyReply(n.optString("title"),n.optString("body"),n.optString("route","/CHAT"));break;
 case "getNotificationPermission":value=notificationPermission();break;
 case "openNotificationSettings":startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));value=true;break;
 case "requestNotifications":if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){if(notificationRequestId!=null)throw new IllegalStateException();notificationRequestId=id;getPreferences(MODE_PRIVATE).edit().putBoolean("notificationAsked",true).apply();requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},NOTIFY_PERMISSION);return;}value=notificationPermission();break;
 case "download":JSONObject d=p.getJSONObject("value");askDownload(d.getString("url"),d.optString("name","download"),d.optString("mime","application/octet-stream"));value=true;break;
 default:throw new IllegalArgumentException("Unsupported action");}
 reply(id,value,null);}catch(Exception e){reply(id,null,"操作暂未完成");}});}}
 private void reply(String id,Object value,String error){try{JSONObject data=new JSONObject();data.put("id",id);data.put("value",value==null?JSONObject.NULL:value);if(error!=null)data.put("error",error);web.evaluateJavascript("dispatchEvent(new CustomEvent('matrix-native-result',{detail:"+data.toString()+"}))",null);}catch(Exception ignored){}}
 private void createChannel(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("matrix-replies","小可的回复",NotificationManager.IMPORTANCE_DEFAULT));}
 private boolean notifyReply(String title,String body,String route){if(!"granted".equals(notificationPermission()))return false;if(!route.matches("/CHAT(/[a-f0-9-]+)?"))route="/CHAT";Intent intent=new Intent(this,MatrixActivity.class).putExtra("route",route).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pending=PendingIntent.getActivity(this,route.hashCode(),intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notification=new Notification.Builder(this,"matrix-replies").setSmallIcon(R.drawable.notification_icon).setContentTitle(title.substring(0,Math.min(120,title.length()))).setContentText(body.substring(0,Math.min(300,body.length()))).setContentIntent(pending).setAutoCancel(true).build();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(route.hashCode(),notification);return true;}
 private void askDownload(String url,String name,String mime){if(!trusted(url))return;downloadUrl=url;downloadMime=mime;downloadName=name;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime==null?"application/octet-stream":mime).putExtra(Intent.EXTRA_TITLE,name.replaceAll("[\\/:*?\"<>|]","_"));try{startActivityForResult(intent,43);}catch(ActivityNotFoundException e){toast("没有可用的保存位置");}}
 private void download(Uri destination,String source){String cookies=CookieManager.getInstance().getCookie(source);io.submit(()->{HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL(source).openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(120000);connection.setInstanceFollowRedirects(false);if(cookies!=null)connection.setRequestProperty("Cookie",cookies);connection.setRequestProperty("User-Agent",MatrixConfig.USER_AGENT);if(connection.getResponseCode()!=200)throw new IOException("Download failed");try(InputStream input=connection.getInputStream();OutputStream output=getContentResolver().openOutputStream(destination,"w")){byte[] buffer=new byte[65536];int count;while((count=input.read(buffer))!=-1)output.write(buffer,0,count);}runOnUiThread(()->toast("文件已保存"));}catch(Exception e){runOnUiThread(()->toast("下载没有完成，请重新尝试"));}finally{if(connection!=null)connection.disconnect();}});}
 private void showOffline(){runOnUiThread(()->{if(root.findViewWithTag("offline")!=null)return;LinearLayout panel=new LinearLayout(this);panel.setTag("offline");panel.setOrientation(LinearLayout.VERTICAL);panel.setGravity(Gravity.CENTER);panel.setPadding(32,32,32,32);panel.setBackgroundColor(Color.rgb(9,9,9));TextView text=new TextView(this);text.setTextColor(Color.WHITE);text.setTextSize(18);text.setText("暂时连接不上 Matrix。\n\n已提交的任务仍在云端处理。");Button retry=new Button(this);retry.setText("重新连接");retry.setOnClickListener(v->{root.removeView(panel);web.loadUrl(MatrixConfig.SERVER_URL);});panel.addView(text);panel.addView(retry);root.addView(panel,new FrameLayout.LayoutParams(-1,-1));});}
 private void toast(String text){Toast.makeText(this,text,Toast.LENGTH_SHORT).show();}
 private void hideFullscreen(){if(fullscreen!=null){root.removeView(fullscreen);fullscreen=null;web.setVisibility(View.VISIBLE);fullscreenCallback.onCustomViewHidden();fullscreenCallback=null;}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==NOTIFY_PERMISSION&&notificationRequestId!=null){String id=notificationRequestId;notificationRequestId=null;if(trusted(web.getUrl()))reply(id,notificationPermission(),null);}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);String route=intent.getStringExtra("route");if(route!=null&&route.matches("/CHAT(/[a-f0-9-]+)?"))web.loadUrl(MatrixConfig.SERVER_URL+route);}
 @Override public void onBackPressed(){if(fullscreen!=null){hideFullscreen();return;}web.evaluateJavascript("(()=>{const d=document.querySelector('dialog[open]');if(d){d.dispatchEvent(new Event('cancel',{cancelable:true}));return true;}const overlay=document.querySelector('.modal-backdrop:not(.is-hidden),.lightbox-backdrop:not(.is-hidden)');if(overlay){dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));return true;}return false;})()",result->{if("true".equals(result))return;if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setMessage("退出 CoreNyan？云端任务会继续执行。").setNegativeButton("取消",null).setPositiveButton("退出",(d,w)->closeWithMotion()).show();});}
 private void closeWithMotion(){
  if(closing)return;closing=true;
  final Handler timer=new Handler(Looper.getMainLooper());final Runnable done=()->{if(!isFinishing())finish();};
  timer.postDelayed(done,CLOSE_TIMEOUT_MS);
  if(!trusted(web.getUrl())){timer.removeCallbacks(done);done.run();return;}
  web.evaluateJavascript("window.MatrixTerminal ? window.MatrixTerminal.close() : 0",result->{
   int delay=0;try{delay=Math.max(0,Math.min(CLOSE_MAX_MS,Integer.parseInt(result)));}catch(Exception ignored){}
   timer.removeCallbacks(done);timer.postDelayed(done,delay);
  });
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK_FILE&&fileCallback!=null){fileCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));fileCallback=null;}else if(request==43&&result==RESULT_OK&&data!=null&&data.getData()!=null&&downloadUrl!=null){download(data.getData(),downloadUrl);downloadUrl=null;}}
 @Override protected void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}
 @Override protected void onPause(){CookieManager.getInstance().flush();super.onPause();}
 @Override protected void onResume(){super.onResume();if(web!=null)web.evaluateJavascript("dispatchEvent(new Event('focus'))",null);}
 @Override protected void onDestroy(){if(fileCallback!=null)fileCallback.onReceiveValue(null);io.shutdown();web.removeJavascriptInterface("MatrixBridge");web.destroy();super.onDestroy();}
}
